<template><div class="panel"><div class="toolbar"><h2 class="page-title">水果分类</h2><div class="spacer"/><el-button type="primary" @click="edit()">新增分类</el-button></div><el-table :data="items"><el-table-column prop="id" label="ID" width="70"/><el-table-column label="图标" width="80"><template #default="s"><span style="font-size:24px">{{s.row.icon}}</span></template></el-table-column><el-table-column prop="name" label="分类名称"/><el-table-column prop="sort" label="排序" width="100"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="del(s.row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="分类" width="420px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="Emoji 图标"><el-input v-model="form.icon"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';import{ElMessage,ElMessageBox}from'element-plus';const items=ref<any[]>([]),visible=ref(false),form=reactive<any>({id:0,name:'',icon:'🍏',sort:0,enabled:true});async function load(){items.value=await api.get('/admin/categories')}function edit(r?:any){Object.assign(form,r||{id:0,name:'',icon:'🍏',sort:0,enabled:true});visible.value=true}async function save(){const{id,...data}=form;id?await api.put(`/admin/categories/${id}`,data):await api.post('/admin/categories',data);visible.value=false;ElMessage.success('已保存');load()}async function del(r:any){await ElMessageBox.confirm(`删除分类“${r.name}”？`,'确认');await api.delete(`/admin/categories/${r.id}`);load()}onMounted(load)</script>
